/**
 * 重置为 Mock 数据（调试用）
 * 清空用户数据并开启默认演示数据开关
 * @returns {Promise}
 */
export function resetToMockData() {
  return new Promise((resolve, reject) => {
    // 1. 清空用户数据缓存
    courseCache = []
    examCache = []
    taskCache = []

    // 2. 开启默认演示数据开关
    useMockDataCache = true

    let saved = 0
    let hasError = false
    const total = 4 // 清空3个数据 + 开启开关

    const checkComplete = (success) => {
      if (!success) hasError = true
      saved++
      if (saved >= total) {
        if (hasError) {
          reject(new Error('Failed to reset some data'))
        } else {
          resolve()
        }
      }
    }

    // 3. 清空 Storage 中的用户数据
    storage.set({
      key: STORAGE_KEYS.COURSES,
      value: JSON.stringify([]),
      success: () => checkComplete(true),
      fail: () => checkComplete(false)
    })

    storage.set({
      key: STORAGE_KEYS.EXAMS,
      value: JSON.stringify([]),
      success: () => checkComplete(true),
      fail: () => checkComplete(false)
    })

    storage.set({
      key: STORAGE_KEYS.TASKS,
      value: JSON.stringify([]),
      success: () => checkComplete(true),
      fail: () => checkComplete(false)
    })

    // 4. 开启默认演示数据开关
    storage.set({
      key: STORAGE_KEYS.DEBUG_USE_MOCK_DATA,
      value: 'true',
      success: () => checkComplete(true),
      fail: () => checkComplete(false)
    })
  })
}

